  test('a customer rates a resolved ticket of their organisation', () => {
    const store = createStore();
    const id = resolvedTicket(store);
    const t = portal.rateTicket(store, acme, id, 4, { now: NOW });
    assert.equal(t.rating, 4);
    assert.equal(t.rated_at, NOW.toISOString());
    assert.equal(store.getTicket(id).rating, 4);
  });

  test('a score that is not a whole number from 1 to 5 is refused', () => {
    const store = createStore();
    const id = resolvedTicket(store);
    for (const bad of [0, 6, 3.5, -1, NaN, '4', null, undefined]) {
