  // Postgres: one UPDATE ... WHERE id = $1 AND status = 'resolved' AND rating IS NULL.
  rateTicket(id, { rating, rated_at }) {
    const t = tickets.get(id);
    if (!t) throw new Error(`no ticket ${id}`);
    if (t.status !== 'resolved' || t.rating != null) return null;
    Object.assign(t, { rating, rated_at });
