  const LOW_SCORE = 2;

  // The customer rates a resolved ticket once. The organisation is checked first, so another organisation's ticket
  // looks exactly like a missing one whatever the score or status.
  function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
    const t = getMyTicket(store, customer, id);
    if (!t) return null;
    if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('a rating is a whole number from 1 to 5');
    if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket`);
    if (t.rating != null) throw new Error('this ticket is already rated');
    const rated = store.rateTicket(id, { rating: score, rated_at: now.toISOString() });
    if (!rated) throw new Error('this ticket is already rated or no longer resolved');
    if (score <= LOW_SCORE && rated.owner_id) notifyAgent(store, rated.owner_id, { type: 'ticket_rated_low', ticketId: id, score });
    return getMyTicket(store, customer, id);
  }
