- [ ] 3. Create `src/jobs/rating-summary.js`:
  ```js
  'use strict';
  // Nightly. Writes exports/agent-ratings.json: for each agent, how many ratings their tickets received in the past
  // seven days and the average score. A ticket counts for its owner at the time the job runs.
  const fs = require('node:fs');
  const path = require('node:path');
  const { EXPORT_DIR } = require('./export-tickets');

  const WINDOW_DAYS = 7;
  const DAY = 24 * 60 * 60 * 1000;

  function summarise(store, { now = new Date() } = {}) {
    const to = now.getTime();
    const from = to - WINDOW_DAYS * DAY;
    const byAgent = new Map();
    for (const t of store.listTickets()) {
      if (t.rating == null || !t.owner_id) continue;
      const at = new Date(t.rated_at).getTime();
      if (at < from || at > to) continue;
      const s = byAgent.get(t.owner_id) || { n: 0, sum: 0 };
      s.n += 1;
      s.sum += t.rating;
      byAgent.set(t.owner_id, s);
    }
    return [...byAgent]
      .sort(([a], [b]) => a - b)
      .map(([agentId, s]) => ({ agent_id: agentId, ratings: s.n, average: Math.round((s.sum / s.n) * 100) / 100 }));
  }

  function writeRatingSummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
    const agents = summarise(store, { now });
    const body = { generated_at: now.toISOString(), since: new Date(now.getTime() - WINDOW_DAYS * DAY).toISOString(), agents };
    fs.mkdirSync(dir, { recursive: true });
    const file = path.join(dir, 'agent-ratings.json');
    fs.writeFileSync(file, JSON.stringify(body, null, 2) + '\n');
    return { file, agents: agents.length };
  }

  module.exports = { summarise, writeRatingSummary, WINDOW_DAYS };
  ```
